@props([
    'name' => null,
    'value' => null,
    'length' => 6,
    'mode' => 'numeric',
    'invalid' => false,
    'disabled' => false,
    'size' => null,
    'separated' => null,
    'inputOtpId' => null,
    'shortcut' => true,
])

@aware([
    'fieldInvalid' => false,
    'controlId' => null,
])

@php
    $invalid = $invalid || $fieldInvalid;

    $length = max(1, (int) $length);
    $mode = in_array($mode, ['numeric', 'alphanumeric'], true) ? $mode : 'numeric';

    $inputOtpId = filled($inputOtpId)
        ? $inputOtpId
        : (filled($name) ? $name : 'input-otp-'.str_replace('.', '', uniqid('', true)));
    $controlId = filled($controlId) ? $controlId : $inputOtpId;

    $scalarValue = filled($value) ? (string) $value : '';
    $scalarValue = mb_substr($scalarValue, 0, $length);

    $useSeparator = $separated === null
        ? ($length >= 4 && $length % 2 === 0)
        : (bool) $separated;

    $half = (int) floor($length / 2);

    $rootAttributes = $attributes
        ->except(['shortcut', 'separated', 'mode', 'length', 'value', 'name'])
        ->class([
            'input-otp flex min-w-0 items-center gap-2',
            'w-full' => ! filled($attributes->get('class')),
        ])
        ->merge([
            'data-input-otp' => true,
            'data-input-otp-id' => $inputOtpId,
            'data-input-otp-length' => (string) $length,
            'data-input-otp-mode' => $mode,
            'role' => 'group',
        ]);

    if ($disabled) {
        $rootAttributes = $rootAttributes->merge(['data-disabled' => 'true']);
    }

    if ($invalid) {
        $rootAttributes = $rootAttributes->merge(['data-invalid' => 'true']);
    }

    if (mb_strlen($scalarValue) === $length) {
        $rootAttributes = $rootAttributes->merge(['data-complete' => 'true']);
    }
@endphp

<div {{ $rootAttributes }}>
    @if (filled($name))
        <input type="hidden" name="{{ $name }}" value="{{ $scalarValue }}" data-input-otp-hidden-input />
    @else
        <input type="hidden" value="{{ $scalarValue }}" data-input-otp-hidden-input />
    @endif

    @if ($shortcut)
        @if ($useSeparator)
            <x-ui::input-otp.group>
                @for ($i = 0; $i < $half; $i++)
                    <x-ui::input-otp.slot :index="$i" :value="$scalarValue" />
                @endfor
            </x-ui::input-otp.group>

            <x-ui::input-otp.separator />

            <x-ui::input-otp.group>
                @for ($i = $half; $i < $length; $i++)
                    <x-ui::input-otp.slot :index="$i" :value="$scalarValue" />
                @endfor
            </x-ui::input-otp.group>
        @else
            <x-ui::input-otp.group>
                @for ($i = 0; $i < $length; $i++)
                    <x-ui::input-otp.slot :index="$i" :value="$scalarValue" />
                @endfor
            </x-ui::input-otp.group>
        @endif
    @else
        {{ $slot }}
    @endif
</div>

@php
    $separatorClasses = collect([
        'input-otp__separator',
        'flex shrink-0 items-center justify-center text-zinc-400 dark:text-zinc-500',
    ])->implode(' ');
@endphp

<div {{
    $attributes->class($separatorClasses)->merge([
        'role' => 'separator',
        'aria-hidden' => 'true',
        'data-input-otp-separator' => true,
    ])
}}>
    @if ($slot->isEmpty())
        <span class="text-sm font-medium">-</span>
    @else
        {{ $slot }}
    @endif
</div>

@aware([
    'size' => null,
    'invalid' => false,
    'fieldInvalid' => false,
    'disabled' => false,
    'mode' => 'numeric',
    'length' => 6,
    'inputOtpId' => null,
    'name' => null,
    'controlId' => null,
])

@props([
    'index' => 0,
    'invalid' => false,
    'disabled' => false,
    'size' => null,
    'value' => null,
])

@php
    use App\Support\Stencil\Form\FormControlClassMap;
    use App\Support\Stencil\Interaction\InteractionStateAttributes;

    $formControl = app(FormControlClassMap::class);
    $interactionState = app(InteractionStateAttributes::class);

    $isInvalid = $invalid || $fieldInvalid;
    $index = max(0, (int) $index);
    $length = max(1, (int) $length);
    $mode = in_array($mode, ['numeric', 'alphanumeric'], true) ? $mode : 'numeric';

    $resolvedInputOtpId = filled($inputOtpId)
        ? $inputOtpId
        : (filled($name) ? $name : null);
    $resolvedControlId = filled($controlId) ? $controlId : $resolvedInputOtpId;

    $scalarValue = filled($value) ? (string) $value : '';
    $char = mb_substr($scalarValue, $index, 1);

    $slotId = filled($resolvedControlId)
        ? $resolvedControlId.($index === 0 ? '' : '-'.$index)
        : null;

    $ariaLabel = __('stencil-ui::messages.input_otp_digit', [
        'position' => $index + 1,
        'length' => $length,
    ]);

    $slotClasses = collect([
        'input-otp__slot',
        'text-center font-medium tabular-nums !px-0',
        $size === 'sm' ? 'w-8' : 'w-9',
        $formControl->fieldSurfaceClasses($size, includeReadOnly: false, cursor: 'text'),
        $formControl->invalidFieldClasses(),
        $isInvalid ? 'border-red-500 focus-visible:ring-red-500/20 dark:border-red-500' : null,
    ])->filter()->implode(' ');

    $inputAttributes = $interactionState->apply(
        $attributes
            ->except(['index', 'invalid', 'disabled', 'size'])
            ->class($slotClasses)
            ->merge([
                'type' => 'text',
                'inputmode' => $mode === 'numeric' ? 'numeric' : 'text',
                'autocomplete' => $index === 0 ? 'one-time-code' : 'off',
                'autocapitalize' => 'characters',
                'autocorrect' => 'off',
                'spellcheck' => 'false',
                'aria-label' => $ariaLabel,
                'data-input-otp-slot' => true,
                'data-index' => (string) $index,
                'value' => $char,
            ]),
        ['nativeDisabled' => true],
    );

    if ($mode === 'numeric') {
        $inputAttributes = $inputAttributes->merge(['pattern' => '[0-9]*']);
    }

    if ($isInvalid) {
        $inputAttributes = $inputAttributes->merge(['aria-invalid' => 'true']);
    }

    if ($disabled) {
        $inputAttributes = $inputAttributes->merge(['disabled' => true]);
    }

    if (filled($slotId)) {
        $inputAttributes = $inputAttributes->merge(['id' => $slotId]);
    }
@endphp

<input {{ $inputAttributes }} />

/**
 * Stencil — accessible OTP / PIN input (vanilla JS, no Alpine).
 */

const INPUT_OTP_SELECTOR = '[data-input-otp]';
const initialized = new WeakSet();

/**
 * @param {ParentNode} root
 */
export function initInputOtps(root = document) {
    root.querySelectorAll(INPUT_OTP_SELECTOR).forEach((element) => {
        if (!(element instanceof HTMLElement)) {
            return;
        }

        if (initialized.has(element)) {
            return;
        }

        initialized.add(element);
        bindInputOtp(element);
    });
}

/**
 * @param {HTMLElement} root
 */
function bindInputOtp(root) {
    /** @type {HTMLInputElement | null} */
    const hiddenInput = root.querySelector('[data-input-otp-hidden-input]');

    if (!(hiddenInput instanceof HTMLInputElement)) {
        return;
    }

    const mode =
        root.getAttribute('data-input-otp-mode') === 'alphanumeric' ? 'alphanumeric' : 'numeric';

    const lengthAttr = Number.parseInt(root.getAttribute('data-input-otp-length') ?? '', 10);

    /**
     * @returns {HTMLInputElement[]}
     */
    function slots() {
        return Array.from(root.querySelectorAll('[data-input-otp-slot]'))
            .filter((node) => node instanceof HTMLInputElement)
            .sort((a, b) => {
                const ai = Number.parseInt(a.dataset.index ?? '', 10);
                const bi = Number.parseInt(b.dataset.index ?? '', 10);

                return (Number.isFinite(ai) ? ai : 0) - (Number.isFinite(bi) ? bi : 0);
            });
    }

    const slotElements = slots();
    const length = Number.isFinite(lengthAttr) && lengthAttr > 0 ? lengthAttr : slotElements.length;

    if (slotElements.length === 0) {
        return;
    }

    /**
     * @param {string} char
     */
    function isAllowedChar(char) {
        if (mode === 'numeric') {
            return /^[0-9]$/.test(char);
        }

        return /^[a-zA-Z0-9]$/.test(char);
    }

    /**
     * @param {string} raw
     */
    function sanitize(raw) {
        return Array.from(raw)
            .map((char) => (mode === 'alphanumeric' ? char.toUpperCase() : char))
            .filter(isAllowedChar)
            .join('')
            .slice(0, length);
    }

    function dispatchValueEvents(target) {
        target.dispatchEvent(new Event('input', { bubbles: true }));
        target.dispatchEvent(new Event('change', { bubbles: true }));
    }

    function isDisabled() {
        return root.hasAttribute('data-disabled') || hiddenInput.disabled;
    }

    /**
     * @param {{ dispatch?: boolean }} [options]
     */
    function syncFromSlots(options = {}) {
        const value = slotElements
            .slice(0, length)
            .map((slot) => slot.value.slice(0, 1))
            .join('');

        const previous = hiddenInput.value;
        hiddenInput.value = value;
        root.dataset.complete = value.length === length ? 'true' : 'false';

        if (options.dispatch !== false && previous !== value) {
            dispatchValueEvents(hiddenInput);
        }
    }

    /**
     * @param {string} value
     * @param {{ focusIndex?: number | null, dispatch?: boolean }} [options]
     */
    function applyValue(value, options = {}) {
        const next = sanitize(value);

        slotElements.forEach((slot, index) => {
            slot.value = next.charAt(index) ?? '';
        });

        syncFromSlots({ dispatch: options.dispatch });

        if (typeof options.focusIndex === 'number') {
            const target =
                slotElements[Math.min(Math.max(options.focusIndex, 0), slotElements.length - 1)];
            target?.focus();
            target?.select();
        }
    }

    /**
     * @param {number} index
     */
    function focusSlot(index) {
        const target = slotElements[Math.min(Math.max(index, 0), slotElements.length - 1)];
        if (!target || target.disabled) {
            return;
        }

        target.focus();
        target.select();
    }

    slotElements.forEach((slot, index) => {
        slot.addEventListener('focus', () => {
            slot.select();
        });

        slot.addEventListener('click', () => {
            slot.select();
        });

        slot.addEventListener('paste', (event) => {
            if (isDisabled() || slot.disabled) {
                return;
            }

            event.preventDefault();

            const pasted = event.clipboardData?.getData('text') ?? '';
            const sanitized = sanitize(pasted);

            if (sanitized === '') {
                return;
            }

            const chars = Array.from(sanitized);
            const next = slotElements.map((item) => item.value.slice(0, 1));

            chars.forEach((char, offset) => {
                const targetIndex = index + offset;
                if (targetIndex < length) {
                    next[targetIndex] = char;
                }
            });

            applyValue(next.join(''), {
                focusIndex: Math.min(index + chars.length, length - 1),
            });
        });

        slot.addEventListener('input', () => {
            if (isDisabled() || slot.disabled) {
                return;
            }

            const raw = slot.value;
            const sanitized = sanitize(raw);

            if (sanitized === '') {
                slot.value = '';
                syncFromSlots();
                return;
            }

            if (raw.length > 1) {
                // Mobile OTP autofill / multi-char insert into one slot.
                const next = slotElements.map((item) => item.value.slice(0, 1));
                const chars = Array.from(sanitized);

                chars.forEach((char, offset) => {
                    const targetIndex = index + offset;
                    if (targetIndex < length) {
                        next[targetIndex] = char;
                    }
                });

                applyValue(next.join(''), {
                    focusIndex: Math.min(index + chars.length, length - 1),
                });

                return;
            }

            const char = sanitized.charAt(sanitized.length - 1);
            slot.value = char;
            syncFromSlots();

            if (index < length - 1) {
                focusSlot(index + 1);
            }
        });

        slot.addEventListener('keydown', (event) => {
            if (isDisabled() || slot.disabled) {
                return;
            }

            switch (event.key) {
                case 'Backspace':
                    event.preventDefault();

                    if (slot.value !== '') {
                        slot.value = '';
                        syncFromSlots();
                        break;
                    }

                    if (index > 0) {
                        const previous = slotElements[index - 1];
                        if (previous) {
                            previous.value = '';
                            syncFromSlots();
                            focusSlot(index - 1);
                        }
                    }
                    break;
                case 'Delete':
                    event.preventDefault();
                    slot.value = '';
                    syncFromSlots();
                    break;
                case 'ArrowLeft':
                    event.preventDefault();
                    focusSlot(index - 1);
                    break;
                case 'ArrowRight':
                    event.preventDefault();
                    focusSlot(index + 1);
                    break;
                case 'Home':
                    event.preventDefault();
                    focusSlot(0);
                    break;
                case 'End':
                    event.preventDefault();
                    focusSlot(length - 1);
                    break;
                default:
                    break;
            }
        });
    });

    // Seed slots from the hidden input when the server provided a value.
    if (hiddenInput.value !== '') {
        applyValue(hiddenInput.value, { dispatch: false });
    } else {
        syncFromSlots({ dispatch: false });
    }
}

document.addEventListener('stencil:mount', (event) => {
    if (!(event instanceof CustomEvent)) {
        return;
    }

    const mountRoot = event.detail?.root;

    if (!(mountRoot instanceof HTMLElement)) {
        return;
    }

    initInputOtps(mountRoot);
});

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => initInputOtps());
    } else {
        initInputOtps();
    }
}
